def depth_first_order(graph, start):
    stack = [start]
    visited = {}
    order = []
    while len(stack) > 0:
        room = stack.pop()
        if room in visited:
            continue
        visited[room] = True
        order.append(room)
        for neighbor in graph[room]:
            if neighbor not in visited:
                stack.append(neighbor)
    return order

